//! `pin-refresh`: rewrites every World pin, its identity file and the preproduction manifest to the
//! values of the tree, so a stale or merge-conflicted pin is regenerated by one command instead of
//! copying the digests from two `pin-check` refusals by hand. Each pin keeps its reviewed
//! `entry_start`; `pin-check` stays the gate that proves the result.

use std::fs;
use std::path::Path;

use oteryn_world_bundle_compiler::Error;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

use super::{
    PIN_SCHEMA, PINS, Pin, build_twice, derive_identity, hex, identity_text, inputs_digest, read,
};

/// The World whose bundle the preproduction topology manifest serves, and that manifest.
const PREPROD_MANIFEST: (&str, &str) = ("oteryn", "deploy/synology-game/preprod-topology.toml");

/// Refreshes every pin from the tree's staged inputs (`inputs_digest` reads the git index, so the
/// inputs are staged first). Returns the JSON summary.
pub(super) fn run(root: &Path) -> Result<Value, Error> {
    let pins = root.join(PINS);
    let tree = inputs_digest(root)?;
    let mut reports = Vec::new();
    for slug in super::pin_slugs(&pins)? {
        let fail = |what: String| Error::Format(format!("pin {slug}: {what}"));
        let path = pins.join(format!("{slug}.json"));
        let mut old: Value =
            serde_json::from_slice(&read(&path)?).map_err(|e| fail(e.to_string()))?;
        if old["schema"] == "OTERYN_WORLD_PIN/v1" {
            // Refresh is the migration path; pin-check accepts only v2.
            if let Some(fields) = old.as_object_mut() {
                fields.remove("inputs_digest");
            }
        } else if old["schema"] != PIN_SCHEMA {
            return Err(fail(format!("unsupported schema; expected {PIN_SCHEMA}")));
        }
        let old: Pin = serde_json::from_value(old).map_err(|e| fail(e.to_string()))?;
        let identity = derive_identity(root, &slug)?;
        write(
            &pins.join(format!("{slug}.identity.json")),
            &identity_text(&identity)?,
        )?;
        let (bytes, _) = build_twice(root, &identity)?;
        let pin = Pin {
            schema: PIN_SCHEMA.to_owned(),
            digest: hex(&bytes[bytes.len() - 32..]),
            project_format_version: identity.project_format_version.clone(),
            world_schema_version: identity.world_schema_version.clone(),
            content_revision: identity.content_revision.clone(),
            production: false,
            entry_start: old.entry_start,
        };
        let text = serde_json::to_string_pretty(&pin).map_err(|e| fail(e.to_string()))? + "\n";
        write(&path, &text)?;
        if slug == PREPROD_MANIFEST.0 {
            refresh_manifest(&root.join(PREPROD_MANIFEST.1), &old, &pin)?;
        }
        reports.push(json!({"world": slug, "digest": pin.digest, "previous": old.digest}));
    }
    let client_placement_index = refresh_client_placement_pin(root)?;
    Ok(
        json!({"inputs_digest": tree, "pins": reports, "client_placement_index": client_placement_index}),
    )
}

/// Points the manifest's `[world_bundle]` table and `[readiness] map_revision` at the new pin.
fn refresh_manifest(path: &Path, old: &Pin, new: &Pin) -> Result<(), Error> {
    let text = String::from_utf8(read(path)?)
        .map_err(|_| Error::Format(format!("{}: not UTF-8", path.display())))?;
    let mut table = String::new();
    let mut out = String::with_capacity(text.len());
    for line in text.split_inclusive('\n') {
        if line.starts_with('[') {
            table = line.trim().to_owned();
        }
        let mut line = line.replace(&old.digest, &new.digest);
        if table == "[world_bundle]" {
            for (key, value) in [
                ("project_format_version", &new.project_format_version),
                ("world_schema_version", &new.world_schema_version),
                ("content_revision", &new.content_revision),
            ] {
                if line.starts_with(&format!("{key} = ")) {
                    line = format!("{key} = \"{value}\"\n");
                }
            }
        }
        out.push_str(&line);
    }
    write(path, &out)
}

fn write(path: &Path, text: &str) -> Result<(), Error> {
    fs::write(path, text).map_err(|e| Error::Format(format!("{}: {e}", path.display())))
}

/// The native asset loader pins the exact same placement index as the World compiler.
/// Keep this source pin in the owning refresh operation, with the strict loader unchanged.
fn refresh_client_placement_pin(root: &Path) -> Result<Value, Error> {
    let index = read(&root.join("content/world/placements/index.json"))?;
    let digest = hex(&Sha256::digest(&index));
    let path = root.join("crates/client-assets/src/world.rs");
    let text = String::from_utf8(read(&path)?)
        .map_err(|error| Error::Format(format!("{}: {error}", path.display())))?;
    const PREFIX: &str = "pub const PLACEMENT_INDEX_SHA256: &str =\n    \"";
    let (before, after) = text
        .split_once(PREFIX)
        .ok_or_else(|| Error::Format("client placement pin anchor absent".to_owned()))?;
    let (previous, tail) = after
        .split_once('"')
        .ok_or_else(|| Error::Format("client placement pin literal absent".to_owned()))?;
    if previous.len() != 64
        || !previous.bytes().all(|byte| byte.is_ascii_hexdigit())
        || tail.contains(PREFIX)
    {
        return Err(Error::Format(
            "client placement pin shape is not unique SHA-256".to_owned(),
        ));
    }
    write(&path, &format!("{before}{PREFIX}{digest}\"{tail}"))?;
    Ok(
        json!({"path": "content/world/placements/index.json", "previous": previous, "sha256": digest}),
    )
}

#[cfg(test)]
mod client_placement_pin_tests {
    use super::*;

    #[test]
    fn changed_placement_index_refreshes_only_its_client_pin()
    -> Result<(), Box<dyn std::error::Error>> {
        let root = std::env::temp_dir().join(format!(
            "oteryn-client-placement-pin-{}",
            std::process::id()
        ));
        fs::create_dir_all(root.join("content/world/placements"))?;
        fs::create_dir_all(root.join("crates/client-assets/src"))?;
        let index = root.join("content/world/placements/index.json");
        let source = root.join("crates/client-assets/src/world.rs");
        let old = "0".repeat(64);
        let untouched = format!("// neighboring input digest {old}\n");
        let prefix = "pub const PLACEMENT_INDEX_SHA256: &str =\n    \"";
        fs::write(&source, format!("{untouched}{prefix}{old}\";\n"))?;
        fs::write(&index, b"{\"palette\":[],\"regions\":[]}")?;
        let first = refresh_client_placement_pin(&root)?;
        assert_eq!(first["previous"], old);
        let first_pin = first["sha256"].as_str().ok_or("first placement pin")?;
        assert_eq!(
            fs::read_to_string(&source)?,
            format!("{untouched}{prefix}{first_pin}\";\n")
        );
        // A changed source palette is a changed client generation, even with no regions.
        let changed = b"{\"palette\":[{\"source_item_id\":7}],\"regions\":[]}";
        fs::write(&index, changed)?;
        let second = refresh_client_placement_pin(&root)?;
        assert_eq!(second["previous"], first_pin);
        assert_ne!(second["sha256"], first["sha256"]);
        let second_pin = second["sha256"].as_str().ok_or("changed placement pin")?;
        let exact = format!("{untouched}{prefix}{second_pin}\";\n");
        assert_eq!(fs::read_to_string(&source)?, exact);
        assert_eq!(fs::read(&index)?, changed);
        let stable = refresh_client_placement_pin(&root)?;
        assert_eq!(stable["previous"], stable["sha256"]);
        assert_eq!(fs::read_to_string(&source)?, exact);
        fs::remove_dir_all(root)?;
        Ok(())
    }
}
